import gzip, hashlib, json, random
from collections import defaultdict, Counter
from pathlib import Path
from statistics import fmean
root=Path('results/monitoring-study/20261111T121002Z/qualification')
analysis=json.loads((root/'analysis/summary.json').read_text())
audit=json.loads((root/'audit.json').read_text())
print('AUDIT',json.dumps({'status':audit['status'],'checked_counts':audit['checked_counts'],'mismatches':len(audit['mismatches'])}))
print('PRIMARY',json.dumps(analysis['primary']))
ind=next(g for g in audit['primary_M3_minus_M1'] if g['family']=='ALL')
print('INDEPENDENT_PRIMARY',json.dumps(ind))
with gzip.open(root/'decisions.jsonl.gz','rt') as stream:
 rows=[json.loads(line) for line in stream if line.strip()]
data=[r for r in rows if 'skip_reason' not in r]
selected=[r for r in data if r['regime'] in {'missing10','missing30','missing50','structured'} and r['budget'] in {1,2,3}]
bykey=defaultdict(dict)
for r in selected:
 if r['method'] in {'M0','M1','M3','M3_no_consequence'}:
  bykey[(r['episode_id'],r['budget'])][r['method']]=r
metrics=('goal_completion','query_count','false_current_permission','abstention','simulated_cost')
pairs=defaultdict(list)
for bymethod in bykey.values():
 a,b=bymethod['M1'],bymethod['M0']
 pairs[a['parent_id']].append({'family':a['family'],**{m:a[m]-b[m] for m in metrics}})
def quantile(v,p):
 v=sorted(v); j=p*(len(v)-1); k=int(j); return v[k]+(v[min(k+1,len(v)-1)]-v[k])*(j-k)
for family in ['ALL','blocks-strips-typed','logistics-strips-typed']:
 parent={p:rs for p,rs in pairs.items() if family=='ALL' or rs[0]['family']==family}
 vals={p:{m:fmean(r[m] for r in rs) for m in metrics} for p,rs in parent.items()}
 strata=defaultdict(list)
 for p,rs in parent.items():strata[rs[0]['family']].append(p)
 rng=random.Random(71603); samples={m:[] for m in metrics}
 for _ in range(2000):
  draw=[rng.choice(sorted(pool)) for _,pool in sorted(strata.items()) for _ in pool]
  for m in metrics:samples[m].append(fmean(vals[p][m] for p in draw))
 result={'family':family,'parents':len(parent),'paired_decisions':sum(map(len,parent.values())),'effects':{m:{'mean':fmean(v[m] for v in vals.values()),'ci':[quantile(samples[m],.025),quantile(samples[m],.975)]} for m in metrics}}
 print('M1_MINUS_M0_PRIMARY',json.dumps(result))
for regime in ('complete','missing10','missing30','missing50','structured','delayed','noise05','invalidated'):
 for method in ('M0','M1','M3'):
  subset=[r for r in data if r['regime']==regime and r['method']==method]
  print('REGIME',json.dumps({'regime':regime,'method':method,'rows':len(subset),'parents':len({r['parent_id'] for r in subset}),'false_current':sum(r['false_current_permission'] for r in subset),'invalid_suffix_permissions':sum(r['invalid_continuation_permission'] for r in subset),'goal_completions':sum(r['goal_completion'] for r in subset),'queries':sum(r['query_count'] for r in subset),'recovery_invocations':sum(r['recovery_invoked'] for r in subset),'symbolic_repair_returns':sum(r['recovery_success'] for r in subset)}))
print('EXACT_REFERENCE',json.dumps({'evaluated_rows':sum(r['method']=='M4' for r in data),'skips':dict(Counter(r['skip_reason'] for r in rows if 'skip_reason' in r)),'oracle_comparisons':len(analysis['oracle_comparisons'])}))
common=0; mismatched=[]
pairs2=defaultdict(dict)
for r in data:
 if r['method'] in {'M1','M3'}: pairs2[(r['episode_id'],r['budget'])][r['method']]=r
for k,v in pairs2.items():
 if len(v)==2:
  common+=1
  if any(v['M1'][m]!=v['M3'][m] for m in ('goal_completion','query_count','false_current_permission')):
   mismatched.append(k)
print('M1_M3_POINT_DISAGREEMENTS',json.dumps({'paired':common,'disagreement_rows':len(mismatched),'first':mismatched[:10]}))
